    {
      "card_ids": ["C23"],
      "claim": "Mephobarbital, a phenyl-substituted barbiturate, had 71-75% absolute oral bioavailability in human volunteers, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an N-phenyl pyrazolone (antipyrine-like) molecule. All transferable experimental evidence points to high oral bioavailability: close analogues such as edaravone (57%), pirfenidone (high), sulphinpyrazone (90%), clobazam (87-100%), and mephobarbital (71-75%) are all well above the 20% threshold. No affirmative evidence supports F < 20%, so the prediction is high.",
